	req7 := httptest.NewRequest(http.MethodPost, "/jobs/j2/ack", nil)
	srv.ServeHTTP(resp7, req7)
	if resp7.Code != http.StatusConflict {
		t.Fatalf("ack queued not in-flight: expected 409, got %d", resp7.Code)
	}
